import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"6. 个人领地","description":"","frontmatter":{},"headers":[],"relativePath":"claims.md","filePath":"claims.md"}'),d={name:"claims.md"};function l(p,t,i,o,c,r){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="_6-个人领地" tabindex="-1">6. 个人领地 <a class="header-anchor" href="#_6-个人领地" aria-label="Permalink to &quot;6. 个人领地&quot;">​</a></h1><h2 id="_6-1-基本规则" tabindex="-1">6.1 基本规则 <a class="header-anchor" href="#_6-1-基本规则" aria-label="Permalink to &quot;6.1 基本规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>每人可拥有个人领地</td><td><strong>1 块</strong></td></tr><tr><td>初始额度</td><td>1,024 格</td></tr><tr><td>额度恢复</td><td>每小时 +256 格，上限 4,096</td></tr><tr><td>可购买额度</td><td>最多 2,048 格；<strong>实际 5 钻石/格</strong>（见 5.4 价格提示）</td></tr><tr><td>最小边长</td><td>5 格</td></tr><tr><td>最大边长</td><td>64 格</td></tr><tr><td>长宽比</td><td>不超过 4:1</td></tr><tr><td>创建冷却</td><td>30 秒</td></tr><tr><td>重划冷却</td><td>72 小时</td></tr><tr><td>转让冷却</td><td>7 天</td></tr><tr><td>领地传送冷却</td><td>30 秒，免费</td></tr><tr><td>主城保护</td><td>主城全境不可圈地（服务器保护区）</td></tr><tr><td>出生点保护</td><td>每个世界出生点 100 格内不能完整圈地</td></tr></tbody></table><p>领地是 <strong>2D 全高</strong> 的：从基岩到天空都属于同一块领地，不能只圈地下或只圈地面。</p><h2 id="_6-2-创建领地" tabindex="-1">6.2 创建领地 <a class="header-anchor" href="#_6-2-创建领地" aria-label="Permalink to &quot;6.2 创建领地&quot;">​</a></h2><h3 id="金锄手选创建" tabindex="-1">金锄手选创建 <a class="header-anchor" href="#金锄手选创建" aria-label="Permalink to &quot;金锄手选创建&quot;">​</a></h3><ol><li>手持<strong>普通金锄</strong>（不需要额外领取，自己合成即可）。</li><li>左键点第一个角，右键点对角。</li><li>输入：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim create &lt;名字&gt;</span></span></code></pre></div><p>选区必须满足最小/最大边长和长宽比；领地不能与已有领地重叠，也不能建在主城全境，或整个落在任一世界的出生点 100 格内。创建后有 30 秒冷却。</p><h2 id="_6-3-额度与扩容" tabindex="-1">6.3 额度与扩容 <a class="header-anchor" href="#_6-3-额度与扩容" aria-label="Permalink to &quot;6.3 额度与扩容&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim quota              查看已用/剩余额度</span></span>
<span class="line"><span>/pclaim buy &lt;格数&gt;         用余额购买额度（当前实际 5 钻石/格，见 5.4）</span></span>
<span class="line"><span>/pclaim expand &lt;格数&gt; [north|south|east|west|out]</span></span>
<span class="line"><span>/pclaim resize &lt;名字&gt;    用金锄重新选区后应用</span></span></code></pre></div><ul><li>初始 1,024 格，约等于 32×32。</li><li>想建 64×64（4,096 格）需要先扩容到上限。</li><li>扩容和重划共用 72 小时冷却；缩小领地会按规则返还额度。</li><li>额度每小时恢复 256 格，封顶 4,096。</li></ul><h2 id="_6-4-领地保护与旗标" tabindex="-1">6.4 领地保护与旗标 <a class="header-anchor" href="#_6-4-领地保护与旗标" aria-label="Permalink to &quot;6.4 领地保护与旗标&quot;">​</a></h2><p>新领地默认规则：</p><table tabindex="0"><thead><tr><th>行为</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>外人进入（move）</td><td>允许</td><td>领地不是封闭盒子，别人可以走进来</td></tr><tr><td>破坏/放置（build）</td><td>禁止</td><td>包括挖掘、放置、使用桶等</td></tr><tr><td>打开容器（container）</td><td>禁止</td><td>箱子、桶、潜影盒等</td></tr><tr><td>使用按钮/门/拉杆（use）</td><td>禁止</td><td>红石交互也受控</td></tr><tr><td>骑乘（riding）</td><td>禁止</td><td>不能骑领地内的动物/载具</td></tr><tr><td>击杀动物（animalkilling）</td><td>禁止</td><td>保护养殖</td></tr><tr><td>领地内 PvP</td><td>默认关闭</td><td>可在领地内开启</td></tr><tr><td>传送进入（tp）</td><td>禁止</td><td>防止他人直接传进领地</td></tr></tbody></table><p>常用旗标命令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim set flag &lt;领地&gt; &lt;旗标&gt; &lt;on|off|clear&gt;   设置整个领地</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; setflag &lt;组&gt; &lt;旗标&gt; &lt;值&gt;   设置某个成员组</span></span>
<span class="line"><span>/pclaim explain &lt;领地&gt; &lt;旗标&gt;                   查看当前值和来源</span></span></code></pre></div><p>常用旗标：<code>build</code>、<code>container</code>、<code>use</code>、<code>move</code>、<code>pvp</code>、<code>tp</code>、<code>riding</code>、<code>animalkilling</code>、<code>mobkilling</code>、<code>ignite</code>、<code>destroy</code>、<code>harvest</code>、<code>hook</code>、<code>leash</code>、<code>shear</code>。</p><blockquote><p>有非屋主在领地内时，屋主不能把 <code>pvp</code> 改成开启（防“骗进来再开 PvP”）。需要先让对方离开。</p></blockquote><h2 id="_6-5-成员与权限组" tabindex="-1">6.5 成员与权限组 <a class="header-anchor" href="#_6-5-成员与权限组" aria-label="Permalink to &quot;6.5 成员与权限组&quot;">​</a></h2><p>每个领地最多 <strong>4 个自定义组</strong>。新建组后，需要给组设置旗标，再把玩家分配进去。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim group &lt;领地&gt; list                         查看现有组</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; create &lt;组名&gt;                新建组</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; assign &lt;玩家&gt; &lt;组名&gt; [时长]  把玩家加入组</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; unassign &lt;玩家&gt;              移出组</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; setflag &lt;组&gt; &lt;旗标&gt; &lt;值&gt;     设置该组权限</span></span>
<span class="line"><span>/pclaim group &lt;领地&gt; delete &lt;组名&gt;                删除组</span></span></code></pre></div><p>给朋友开放建造的典型步骤：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim group myhome create friend</span></span>
<span class="line"><span>/pclaim group myhome setflag friend build on</span></span>
<span class="line"><span>/pclaim group myhome setflag friend container on</span></span>
<span class="line"><span>/pclaim group myhome setflag friend use on</span></span>
<span class="line"><span>/pclaim group myhome assign Steve friend</span></span></code></pre></div><p>也可以直接打开 <code>/pclaim gui</code>，在图形界面里完成大部分成员和旗标操作。</p><h2 id="_6-6-领地传送与转让" tabindex="-1">6.6 领地传送与转让 <a class="header-anchor" href="#_6-6-领地传送与转让" aria-label="Permalink to &quot;6.6 领地传送与转让&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim settp              在当前位置设置领地传送点</span></span>
<span class="line"><span>/pclaim home               回自己的领地（优先使用已设的领地传送点）</span></span>
<span class="line"><span>/pclaim home transfer &lt;玩家&gt;   把领地转让给对方</span></span>
<span class="line"><span>/pclaim home accept        接受别人转来的领地</span></span></code></pre></div><ul><li>领地传送免费，冷却 30 秒。</li><li>转让有 7 天冷却；对方必须输入 <code>/pclaim home accept</code> 才算完成。</li><li>转让后原屋主失去全部权限，操作前确认清楚。</li></ul><h2 id="_6-7-封禁、删除与查询" tabindex="-1">6.7 封禁、删除与查询 <a class="header-anchor" href="#_6-7-封禁、删除与查询" aria-label="Permalink to &quot;6.7 封禁、删除与查询&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim ban &lt;玩家&gt; [领地]      禁止某人进入/使用领地</span></span>
<span class="line"><span>/pclaim unban &lt;玩家&gt; [领地]    解除封禁</span></span>
<span class="line"><span>/pclaim info [领地]            查看领地信息</span></span>
<span class="line"><span>/pclaim list                   列出自己的领地</span></span>
<span class="line"><span>/pclaim map                    在聊天栏显示附近领地地图</span></span>
<span class="line"><span>/pclaim borders                开关领地边界显示</span></span>
<span class="line"><span>/pclaim select &lt;领地&gt;          选中已有领地的范围</span></span>
<span class="line"><span>/pclaim trapped                卡在领地内时脱困</span></span></code></pre></div><p>删除领地：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pclaim delete &lt;领地&gt;</span></span></code></pre></div><p>需要在 10 秒内再次确认。删除不可恢复，里面的建筑不会返还。</p><h2 id="_6-8-个人领地限制一览" tabindex="-1">6.8 个人领地限制一览 <a class="header-anchor" href="#_6-8-个人领地限制一览" aria-label="Permalink to &quot;6.8 个人领地限制一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>数值</th></tr></thead><tbody><tr><td>每人领地数</td><td>1</td></tr><tr><td>初始额度</td><td>1,024</td></tr><tr><td>额度上限</td><td>4,096</td></tr><tr><td>每小时恢复</td><td>256</td></tr><tr><td>购买价格</td><td>当前实际 5 钻石/格（标价 0.05，见 5.4）</td></tr><tr><td>最多购买</td><td>2,048 格</td></tr><tr><td>最小/最大边长</td><td>5 / 64</td></tr><tr><td>最大长宽比</td><td>4:1</td></tr><tr><td>创建冷却</td><td>30 秒</td></tr><tr><td>扩容冷却</td><td>72 小时</td></tr><tr><td>转让冷却</td><td>7 天</td></tr><tr><td>传送冷却</td><td>30 秒</td></tr><tr><td>自定义组上限</td><td>4</td></tr></tbody></table>`,35)])])}const u=a(d,[["render",l]]);export{g as __pageData,u as default};
